1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上、修订记录衔接不上、成功修订编号在保存历史中不唯一或与已关闭
40	// 清册的申请编号相同）时返回 ErrCorruptState，
41	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
42	func Open(dir string) (*Store, error) {
43		if dir == "" {
44			return nil, errors.New("retention: 保存位置不能为空")
45		}
46		if err := os.MkdirAll(dir, 0o755); err != nil {
47			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
48		}
49		s := &Store{dir: dir}
50		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
51		if _, err := s.load(); err != nil {
52			return nil, err
53		}
54		return s, nil
55	}
56	
57	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
58	func (s *Store) Close() error { return nil }
59	
60	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
61	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
62	
63	// lock 取得跨进程排他锁，返回解锁函数。
64	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
65	func (s *Store) lock() (func(), error) {
66		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
67		if err != nil {
68			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
69		}
70		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
71			f.Close()
72			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
73		}
74		return func() {
75			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
76			_ = f.Close()
77		}, nil
78	}
79	
80	// rlock 取得跨进程共享锁，用于只读核对。
81	func (s *Store) rlock() (func(), error) {
82		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
83		if err != nil {
84			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
85		}
86		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
87			f.Close()
88			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
89		}
90		return func() {
91			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
92			_ = f.Close()
93		}, nil
94	}
95	
96	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
97	//
98	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
99	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
100	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
101	// 绝不只使用前一段内容，也不会改动原文件。
102	//
103	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
104	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
105	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
106	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
107	//
108	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
109	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
110	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
111	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
112	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
113	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
114	//
115	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
116	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
117	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
118	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
119	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
120	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
121	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
122	// 同时指明修订编号。
123	//
124	// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
125	// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
126	// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
127	// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
128	// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
129	// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
130	// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
131	// 档案，与清册冲突时指出修订所属档案与清册申请编号。
132	func (s *Store) load() (*storeData, error) {
133		raw, err := os.ReadFile(s.statePath())
134		if err != nil {
135			if errors.Is(err, os.ErrNotExist) {
136				return newStoreData(), nil
137			}
138			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
139		}
140		trimmed := bytes.TrimSpace(raw)
141		if len(trimmed) == 0 {
142			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
143		}
144		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
145		if string(trimmed) == "null" {
146			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
147		}
148		data := newStoreData()
149		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
150		// 合法对象后面再拼接任何内容都会在这里报错。
151		if err := json.Unmarshal(raw, data); err != nil {
152			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
153		}
154		if data.Archives == nil {
155			data.Archives = map[string]*archiveRecord{}
156		}
157		if data.Manifests == nil {
158			data.Manifests = map[string]*manifestRecord{}
159		}
160		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
161		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
162		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
163		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
164		if err := validateFreezeReleaseRecords(data); err != nil {
165			return nil, err
166		}
167		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
168		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
169		if err := validateManifestConsistency(data); err != nil {
170			return nil, err
171		}
172		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
173		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
174		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
175		for _, ar := range data.Archives {
176			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
177				ar.InitialEnd = ar.End
178			}
179		}
180		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
181		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
182		if err := validateRevisionContinuity(data); err != nil {
183			return nil, err
184		}
185		// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
186		// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
187		if err := validateRevisionIDs(data); err != nil {
188			return nil, err
189		}
190		return data, nil
191	}
192	
193	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
194	//
195	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
196	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
197	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
198	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
199	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
200	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
201	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
202	func validateFreezeReleaseRecords(data *storeData) error {
203		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
204		archiveIDs := make([]string, 0, len(data.Archives))
205		for id := range data.Archives {
206			archiveIDs = append(archiveIDs, id)
207		}
208		sort.Strings(archiveIDs)
209		for _, id := range archiveIDs {
210			ar := data.Archives[id]
211			if ar == nil {
212				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
213					id, ErrCorruptState)
214			}
215			for _, fr := range ar.Freezes {
216				if fr == nil {
217					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
218						id, ErrCorruptState)
219				}
220				if !fr.Released {
221					// 未解除冻结没有解除日期与原因是合法状态。
222					continue
223				}
224				switch {
225				case strings.TrimSpace(fr.ReleaseReason) == "":
226					return fmt.Errorf(
227						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
228						id, fr.ID, ErrCorruptState)
229				case fr.ReleasedOn == nil:
230					return fmt.Errorf(
231						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
232						id, fr.ID, ErrCorruptState)
233				case fr.ReleasedOn.IsZero():
234					return fmt.Errorf(
235						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
236						id, fr.ID, ErrCorruptState)
237				case fr.ReleasedOn.Before(fr.FrozenOn):
238					return fmt.Errorf(
239						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
240						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
241				}
242			}
243		}
244		return nil
245	}
246	
247	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
248	//
249	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
250	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
251	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
252	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
253	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
254	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
255	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
256	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
257	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
258	func validateManifestConsistency(data *storeData) error {
259		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
260		archiveIDs := make([]string, 0, len(data.Archives))
261		for id := range data.Archives {
262			archiveIDs = append(archiveIDs, id)
263		}
264		sort.Strings(archiveIDs)
265		for _, id := range archiveIDs {
266			ar := data.Archives[id]
267			if ar == nil {
268				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
269				continue
270			}
271			if !ar.Destroyed {
272				if ar.ManifestID != "" {
273					return fmt.Errorf(
274						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
275						id, ar.ManifestID, ErrCorruptState)
276				}
277				continue
278			}
279			if ar.ManifestID == "" {
280				return fmt.Errorf(
281					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
282					id, ErrCorruptState)
283			}
284			rec, ok := data.Manifests[ar.ManifestID]
285			if !ok || rec == nil {
286				return fmt.Errorf(
287					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
288					id, ar.ManifestID, ErrCorruptState)
289			}
290			count := 0
291			for _, e := range rec.Entries {
292				if e.ID == id {
293					count++
294				}
295			}
296			if count != 1 {
297				return fmt.Errorf(
298					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
299					id, ar.ManifestID, count, ErrCorruptState)
300			}
301		}
302	
303		applicationIDs := make([]string, 0, len(data.Manifests))
304		for id := range data.Manifests {
305			applicationIDs = append(applicationIDs, id)
306		}
307		sort.Strings(applicationIDs)
308		for _, appID := range applicationIDs {
309			rec := data.Manifests[appID]
310			if rec == nil {
311				return fmt.Errorf(
312					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
313					appID, ErrCorruptState)
314			}
315			seen := make(map[string]int, len(rec.Entries))
316			for _, e := range rec.Entries {
317				seen[e.ID]++
318				ar, ok := data.Archives[e.ID]
319				if !ok || ar == nil {
320					return fmt.Errorf(
321						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
322						appID, e.ID, ErrCorruptState)
323				}
324				if !ar.Destroyed {
325					return fmt.Errorf(
326						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
327						appID, e.ID, ErrCorruptState)
328				}
329				if ar.ManifestID != appID {
330					return fmt.Errorf(
331						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
332						appID, e.ID, ar.ManifestID, ErrCorruptState)
333				}
334			}
335			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
336			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
337			entryIDs := make([]string, 0, len(seen))
338			for id := range seen {
339				entryIDs = append(entryIDs, id)
340			}
341			sort.Strings(entryIDs)
342			for _, id := range entryIDs {
343				if seen[id] > 1 {
344					return fmt.Errorf(
345						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
346						appID, id, seen[id], ErrCorruptState)
347				}
348			}
349		}
350		return nil
351	}
352	
353	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
354	// 是否连续对应。
355	//
356	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
357	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
358	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
359	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
360	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
361	//
362	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
363	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
364	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
365	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
366	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
367	func validateRevisionContinuity(data *storeData) error {
368		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
369		archiveIDs := make([]string, 0, len(data.Archives))
370		for id := range data.Archives {
371			archiveIDs = append(archiveIDs, id)
372		}
373		sort.Strings(archiveIDs)
374		for _, id := range archiveIDs {
375			ar := data.Archives[id]
376			if ar == nil {
377				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
378				continue
379			}
380			if len(ar.Revisions) == 0 {
381				// 没有修订时最初截止日与当前截止日必须相同
382				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
383				if !ar.InitialEnd.Equal(ar.End) {
384					return fmt.Errorf(
385						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
386						id, ar.InitialEnd, ar.End, ErrCorruptState)
387				}
388				continue
389			}
390			for i, rec := range ar.Revisions {
391				if rec == nil {
392					return fmt.Errorf(
393						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
394						id, i+1, ErrCorruptState)
395				}
396			}
397			if ar.InitialEnd.IsZero() {
398				return fmt.Errorf(
399					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
400					id, ar.Revisions[0].ID, ErrCorruptState)
401			}
402			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
403			expected := ar.InitialEnd
404			for _, rec := range ar.Revisions {
405				if !rec.OldEnd.Equal(expected) {
406					return fmt.Errorf(
407						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
408						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
409				}
410				expected = rec.NewEnd
411			}
412			if !ar.End.Equal(expected) {
413				return fmt.Errorf(
414					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
415					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
416			}
417		}
418		return nil
419	}
420	
421	// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
422	// 清册申请编号的互不占用。
423	//
424	// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
425	// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
426	// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
427	// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
428	// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
429	// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
430	//
431	// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
432	// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
433	// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
434	// 作为成功记录存在，一并按损坏处理。
435	func validateRevisionIDs(data *storeData) error {
436		owners := make(map[string]string)
437		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
438		archiveIDs := make([]string, 0, len(data.Archives))
439		for id := range data.Archives {
440			archiveIDs = append(archiveIDs, id)
441		}
442		sort.Strings(archiveIDs)
443		for _, id := range archiveIDs {
444			ar := data.Archives[id]
445			if ar == nil {
446				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
447				continue
448			}
449			for _, rec := range ar.Revisions {
450				if rec == nil {
451					// 空记录已由 validateRevisionContinuity 报告。
452					continue
453				}
454				if strings.TrimSpace(rec.ID) == "" {
455					return fmt.Errorf(
456						"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
457						id, ErrCorruptState)
458				}
459				if owner, ok := owners[rec.ID]; ok {
460					if owner == id {
461						return fmt.Errorf(
462							"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
463							rec.ID, id, ErrCorruptState)
464					}
465					return fmt.Errorf(
466						"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
467						rec.ID, owner, id, ErrCorruptState)
468				}
469				owners[rec.ID] = id
470			}
471		}
472		// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
473		// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
474		appIDs := make([]string, 0, len(data.Manifests))
475		for appID := range data.Manifests {
476			appIDs = append(appIDs, appID)
477		}
478		sort.Strings(appIDs)
479		for _, appID := range appIDs {
480			if owner, ok := owners[appID]; ok {
481				return fmt.Errorf(
482					"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
483					owner, appID, appID, ErrCorruptState)
484			}
485		}
486		return nil
487	}
488	
489	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
490	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
491	func (s *Store) save(data *storeData) error {
492		buf, err := json.MarshalIndent(data, "", "  ")
493		if err != nil {
494			return fmt.Errorf("retention: 状态编码失败: %w", err)
495		}
496		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
497		if err != nil {
498			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
499		}
500		tmpName := tmp.Name()
501		cleanup := func() { _ = os.Remove(tmpName) }
502		if _, err := tmp.Write(buf); err != nil {
503			tmp.Close()
504			cleanup()
505			return fmt.Errorf("retention: 写入状态失败: %w", err)
506		}
507		if err := tmp.Sync(); err != nil {
508			tmp.Close()
509			cleanup()
510			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
511		}
512		if err := tmp.Close(); err != nil {
513			cleanup()
514			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
515		}
516		if err := os.Rename(tmpName, s.statePath()); err != nil {
517			cleanup()
518			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
519		}
520		// 刷目录，确保 rename 在崩溃后仍然落盘。
521		if dir, err := os.Open(s.dir); err == nil {
522			_ = dir.Sync()
523			_ = dir.Close()
524		}
525		return nil
526	}
527	
528	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
529	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
530	func (s *Store) mutate(fn func(*storeData) error) error {
531		s.opMu.Lock()
532		defer s.opMu.Unlock()
533		unlock, err := s.lock()
534		if err != nil {
535			return err
536		}
537		defer unlock()
538		data, err := s.load()
539		if err != nil {
540			return err
541		}
542		if err := fn(data); err != nil {
543			return err
544		}
545		return s.save(data)
546	}
547	
548	// view 在共享锁内重读状态并执行只读查询。
549	func (s *Store) view(fn func(*storeData) error) error {
550		s.opMu.RLock()
551		defer s.opMu.RUnlock()
552		unlock, err := s.rlock()
553		if err != nil {
554			return err
555		}
556		defer unlock()
557		data, err := s.load()
558		if err != nil {
559			return err
560		}
561		return fn(data)
562	}
563

file.content:
package retention

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"syscall"
)

// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
const (
	stateFileName = "retention-state.json"
	lockFileName  = ".retention.lock"
)

// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
//
// 同一个目录可以被本机上的多个程序（进程）同时打开：
// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
type Store struct {
	dir string

	// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
	opMu sync.RWMutex
}

// Open 打开（或创建）一个本地保存位置。
// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
// 对应不上、修订记录衔接不上、成功修订编号在保存历史中不唯一或与已关闭
// 清册的申请编号相同）时返回 ErrCorruptState，
// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
func Open(dir string) (*Store, error) {
	if dir == "" {
		return nil, errors.New("retention: 保存位置不能为空")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
	}
	s := &Store{dir: dir}
	// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
	if _, err := s.load(); err != nil {
		return nil, err
	}
	return s, nil
}

// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
func (s *Store) Close() error { return nil }

func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }

// lock 取得跨进程排他锁，返回解锁函数。
// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
func (s *Store) lock() (func(), error) {
	f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
		f.Close()
		return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
	}
	return func() {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
	}, nil
}

// rlock 取得跨进程共享锁，用于只读核对。
func (s *Store) rlock() (func(), error) {
	f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
		f.Close()
		return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
	}
	return func() {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
	}, nil
}

// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
//
// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
// 绝不只使用前一段内容，也不会改动原文件。
//
// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
//
// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
//
// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
// 同时指明修订编号。
//
// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
// 档案，与清册冲突时指出修订所属档案与清册申请编号。
func (s *Store) load() (*storeData, error) {
	raw, err := os.ReadFile(s.statePath())
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return newStoreData(), nil
		}
		return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
	}
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
	}
	// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
	if string(trimmed) == "null" {
		return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
	}
	data := newStoreData()
	// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
	// 合法对象后面再拼接任何内容都会在这里报错。
	if err := json.Unmarshal(raw, data); err != nil {
		return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
	}
	if data.Archives == nil {
		data.Archives = map[string]*archiveRecord{}
	}
	if data.Manifests == nil {
		data.Manifests = map[string]*manifestRecord{}
	}
	// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
	// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
	// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
	// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
	if err := validateFreezeReleaseRecords(data); err != nil {
		return nil, err
	}
	// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
	// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
	if err := validateManifestConsistency(data); err != nil {
		return nil, err
	}
	// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
	// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
	// 冒充，由 validateRevisionContinuity 按损坏拒绝。
	for _, ar := range data.Archives {
		if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
			ar.InitialEnd = ar.End
		}
	}
	// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
	// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
	if err := validateRevisionContinuity(data); err != nil {
		return nil, err
	}
	// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
	// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
	if err := validateRevisionIDs(data); err != nil {
		return nil, err
	}
	return data, nil
}

// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
//
// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
func validateFreezeReleaseRecords(data *storeData) error {
	// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
	archiveIDs := make([]string, 0, len(data.Archives))
	for id := range data.Archives {
		archiveIDs = append(archiveIDs, id)
	}
	sort.Strings(archiveIDs)
	for _, id := range archiveIDs {
		ar := data.Archives[id]
		if ar == nil {
			return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
				id, ErrCorruptState)
		}
		for _, fr := range ar.Freezes {
			if fr == nil {
				return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
					id, ErrCorruptState)
			}
			if !fr.Released {
				// 未解除冻结没有解除日期与原因是合法状态。
				continue
			}
			switch {
			case strings.TrimSpace(fr.ReleaseReason) == "":
				return fmt.Errorf(
					"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
					id, fr.ID, ErrCorruptState)
			case fr.ReleasedOn == nil:
				return fmt.Errorf(
					"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
					id, fr.ID, ErrCorruptState)
			case fr.ReleasedOn.IsZero():
				return fmt.Errorf(
					"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
					id, fr.ID, ErrCorruptState)
			case fr.ReleasedOn.Before(fr.FrozenOn):
				return fmt.Errorf(
					"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
					id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
			}
		}
	}
	return nil
}

// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
//
// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
// 未销毁且没有清册归属的档案是合法记录，不在此报错。
func validateManifestConsistency(data *storeData) error {
	// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
	archiveIDs := make([]string, 0, len(data.Archives))
	for id := range data.Archives {
		archiveIDs = append(archiveIDs, id)
	}
	sort.Strings(archiveIDs)
	for _, id := range archiveIDs {
		ar := data.Archives[id]
		if ar == nil {
			// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
			continue
		}
		if !ar.Destroyed {
			if ar.ManifestID != "" {
				return fmt.Errorf(
					"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
					id, ar.ManifestID, ErrCorruptState)
			}
			continue
		}
		if ar.ManifestID == "" {
			return fmt.Errorf(
				"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
				id, ErrCorruptState)
		}
		rec, ok := data.Manifests[ar.ManifestID]
		if !ok || rec == nil {
			return fmt.Errorf(
				"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
				id, ar.ManifestID, ErrCorruptState)
		}
		count := 0
		for _, e := range rec.Entries {
			if e.ID == id {
				count++
			}
		}
		if count != 1 {
			return fmt.Errorf(
				"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
				id, ar.ManifestID, count, ErrCorruptState)
		}
	}

	applicationIDs := make([]string, 0, len(data.Manifests))
	for id := range data.Manifests {
		applicationIDs = append(applicationIDs, id)
	}
	sort.Strings(applicationIDs)
	for _, appID := range applicationIDs {
		rec := data.Manifests[appID]
		if rec == nil {
			return fmt.Errorf(
				"retention: 清册 %s 的内容缺失，记录已损坏: %w",
				appID, ErrCorruptState)
		}
		seen := make(map[string]int, len(rec.Entries))
		for _, e := range rec.Entries {
			seen[e.ID]++
			ar, ok := data.Archives[e.ID]
			if !ok || ar == nil {
				return fmt.Errorf(
					"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
					appID, e.ID, ErrCorruptState)
			}
			if !ar.Destroyed {
				return fmt.Errorf(
					"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
					appID, e.ID, ErrCorruptState)
			}
			if ar.ManifestID != appID {
				return fmt.Errorf(
					"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
					appID, e.ID, ar.ManifestID, ErrCorruptState)
			}
		}
		// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
		// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
		entryIDs := make([]string, 0, len(seen))
		for id := range seen {
			entryIDs = append(entryIDs, id)
		}
		sort.Strings(entryIDs)
		for _, id := range entryIDs {
			if seen[id] > 1 {
				return fmt.Errorf(
					"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
					appID, id, seen[id], ErrCorruptState)
			}
		}
	}
	return nil
}

// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
// 是否连续对应。
//
// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
//
// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
func validateRevisionContinuity(data *storeData) error {
	// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
	archiveIDs := make([]string, 0, len(data.Archives))
	for id := range data.Archives {
		archiveIDs = append(archiveIDs, id)
	}
	sort.Strings(archiveIDs)
	for _, id := range archiveIDs {
		ar := data.Archives[id]
		if ar == nil {
			// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
			continue
		}
		if len(ar.Revisions) == 0 {
			// 没有修订时最初截止日与当前截止日必须相同
			// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
			if !ar.InitialEnd.Equal(ar.End) {
				return fmt.Errorf(
					"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
					id, ar.InitialEnd, ar.End, ErrCorruptState)
			}
			continue
		}
		for i, rec := range ar.Revisions {
			if rec == nil {
				return fmt.Errorf(
					"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
					id, i+1, ErrCorruptState)
			}
		}
		if ar.InitialEnd.IsZero() {
			return fmt.Errorf(
				"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
				id, ar.Revisions[0].ID, ErrCorruptState)
		}
		// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
		expected := ar.InitialEnd
		for _, rec := range ar.Revisions {
			if !rec.OldEnd.Equal(expected) {
				return fmt.Errorf(
					"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
					id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
			}
			expected = rec.NewEnd
		}
		if !ar.End.Equal(expected) {
			return fmt.Errorf(
				"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
				id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
		}
	}
	return nil
}

// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
// 清册申请编号的互不占用。
//
// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
//
// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
// 作为成功记录存在，一并按损坏处理。
func validateRevisionIDs(data *storeData) error {
	owners := make(map[string]string)
	// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
	archiveIDs := make([]string, 0, len(data.Archives))
	for id := range data.Archives {
		archiveIDs = append(archiveIDs, id)
	}
	sort.Strings(archiveIDs)
	for _, id := range archiveIDs {
		ar := data.Archives[id]
		if ar == nil {
			// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
			continue
		}
		for _, rec := range ar.Revisions {
			if rec == nil {
				// 空记录已由 validateRevisionContinuity 报告。
				continue
			}
			if strings.TrimSpace(rec.ID) == "" {
				return fmt.Errorf(
					"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
					id, ErrCorruptState)
			}
			if owner, ok := owners[rec.ID]; ok {
				if owner == id {
					return fmt.Errorf(
						"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
						rec.ID, id, ErrCorruptState)
				}
				return fmt.Errorf(
					"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
					rec.ID, owner, id, ErrCorruptState)
			}
			owners[rec.ID] = id
		}
	}
	// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
	// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
	appIDs := make([]string, 0, len(data.Manifests))
	for appID := range data.Manifests {
		appIDs = append(appIDs, appID)
	}
	sort.Strings(appIDs)
	for _, appID := range appIDs {
		if owner, ok := owners[appID]; ok {
			return fmt.Errorf(
				"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
				owner, appID, appID, ErrCorruptState)
		}
	}
	return nil
}

// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
func (s *Store) save(data *storeData) error {
	buf, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return fmt.Errorf("retention: 状态编码失败: %w", err)
	}
	tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
	if err != nil {
		return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
	}
	tmpName := tmp.Name()
	cleanup := func() { _ = os.Remove(tmpName) }
	if _, err := tmp.Write(buf); err != nil {
		tmp.Close()
		cleanup()
		return fmt.Errorf("retention: 写入状态失败: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		cleanup()
		return fmt.Errorf("retention: 刷盘状态失败: %w", err)
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
	}
	if err := os.Rename(tmpName, s.statePath()); err != nil {
		cleanup()
		return fmt.Errorf("retention: 替换状态文件失败: %w", err)
	}
	// 刷目录，确保 rename 在崩溃后仍然落盘。
	if dir, err := os.Open(s.dir); err == nil {
		_ = dir.Sync()
		_ = dir.Close()
	}
	return nil
}

// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
func (s *Store) mutate(fn func(*storeData) error) error {
	s.opMu.Lock()
	defer s.opMu.Unlock()
	unlock, err := s.lock()
	if err != nil {
		return err
	}
	defer unlock()
	data, err := s.load()
	if err != nil {
		return err
	}
	if err := fn(data); err != nil {
		return err
	}
	return s.save(data)
}

// view 在共享锁内重读状态并执行只读查询。
func (s *Store) view(fn func(*storeData) error) error {
	s.opMu.RLock()
	defer s.opMu.RUnlock()
	unlock, err := s.rlock()
	if err != nil {
		return err
	}
	defer unlock()
	data, err := s.load()
	if err != nil {
		return err
	}
	return fn(data)
}

package retention

import (
	"errors"
	"fmt"
)

// 业务规则错误。调用方可用 errors.Is 判断失败类别，具体错误信息会附带上编号等上下文。
var (
	// ErrNotFound 表示档案或相关记录不存在。
	ErrNotFound = errors.New("retention: 档案不存在")
	// ErrDuplicateID 表示档案编号已经登记过。
	ErrDuplicateID = errors.New("retention: 档案编号重复")
	// ErrDestroyed 表示档案已经销毁，不能再执行该操作。
	ErrDestroyed = errors.New("retention: 档案已销毁")
	// ErrBlankField 表示必填的编号、类别或原因为空白。
	ErrBlankField = errors.New("retention: 字段不能为空白")
	// ErrInvalidDate 表示日期缺失或不是真实的日历日期。
	ErrInvalidDate = errors.New("retention: 日期无效")
	// ErrRetentionEndBeforeStart 表示保管截止日早于起算日。
	ErrRetentionEndBeforeStart = errors.New("retention: 保管截止日不能早于起算日")
	// ErrReleaseBeforeFreeze 表示解除日期早于冻结日期。
	ErrReleaseBeforeFreeze = errors.New("retention: 解除日期不能早于冻结日期")
	// ErrDuplicateFreezeID 表示同一档案内冻结编号重复。
	ErrDuplicateFreezeID = errors.New("retention: 冻结编号在同一档案内重复")
	// ErrFreezeNotFound 表示该档案下没有对应编号的冻结。
	ErrFreezeNotFound = errors.New("retention: 冻结不存在")
	// ErrFreezeAlreadyReleased 表示冻结已经解除，不能重复解除。
	ErrFreezeAlreadyReleased = errors.New("retention: 冻结已经解除")
	// ErrEmptyDestructionList 表示销毁名单为空。
	ErrEmptyDestructionList = errors.New("retention: 销毁名单不能为空")
	// ErrDuplicateSelection 表示同一次销毁申请中档案编号重复。
	ErrDuplicateSelection = errors.New("retention: 销毁名单中档案编号重复")
	// ErrNotDestroyable 表示名单中存在未到期或仍有未解除冻结的档案。
	ErrNotDestroyable = errors.New("retention: 存在不能销毁的档案")
	// ErrNotExpired 表示档案尚未到保管截止日。截止日当天才视为到期。
	ErrNotExpired = errors.New("retention: 档案尚未到期")
	// ErrActiveFreeze 表示档案仍有未解除的冻结。
	ErrActiveFreeze = errors.New("retention: 档案存在未解除的冻结")
	// ErrApplicationMismatch 表示申请编号已成功使用，但本次日期或档案集合与原申请不一致。
	ErrApplicationMismatch = errors.New("retention: 申请编号与已成功的申请不一致")
	// ErrArchiveAlreadyOnManifest 表示档案已经出现在另一份成功清册中。
	ErrArchiveAlreadyOnManifest = errors.New("retention: 档案已在其他销毁清册中")
	// ErrRetentionEndChanged 表示提交的原截止日与当前保存值不一致，期限已被他人改动。
	ErrRetentionEndChanged = errors.New("retention: 保管截止日已变化")
	// ErrRevisionConflict 表示修订编号已成功使用但本次内容不同，或与销毁申请编号相互占用。
	ErrRevisionConflict = errors.New("retention: 修订编号冲突")
	// ErrRevisionEndUnchanged 表示新截止日与所提交的原截止日相同。
	ErrRevisionEndUnchanged = errors.New("retention: 新截止日不能等于原截止日")
	// ErrCorruptState 表示状态文件已存在但内容损坏，无法读取已保存的记录。
	// 与“尚未建立记录”（状态文件不存在，按空库打开）明确区分：
	// 出现该错误时打开、查询与办理都会失败，且原文件保持原样。
	ErrCorruptState = errors.New("retention: 无法读取已保存的记录，状态文件已损坏")
)

// RetentionEndChangedError 表示修订提交的原截止日与当前保存值不一致：
// 首次办理时期限已被他人改动，本次修订未生效。CurrentEnd 给出当前保存的截止日。
type RetentionEndChangedError struct {
	ArchiveID  string
	CurrentEnd Date
}

func (e *RetentionEndChangedError) Error() string {
	return fmt.Sprintf("retention: 档案 %s 的保管截止日已变化，当前为 %s: %s",
		e.ArchiveID, e.CurrentEnd, ErrRetentionEndChanged)
}

// Is 支持 errors.Is(err, ErrRetentionEndChanged)。
func (e *RetentionEndChangedError) Is(target error) bool { return target == ErrRetentionEndChanged }

// InvalidDateError 说明 ParseDate 收到的值不是合法的 YYYY-MM-DD 真实日期。
type InvalidDateError struct {
	Value string
}

func (e *InvalidDateError) Error() string {
	return "retention: 日期无效，应为 YYYY-MM-DD 且真实存在: " + e.Value
}

// Is 支持 errors.Is(err, ErrInvalidDate)。
func (e *InvalidDateError) Is(target error) bool { return target == ErrInvalidDate }

