150				}
151				// 核对按当前生效的截止日判断，截止日当天即到期。
152				r, err := s.Check(CheckRequest{
153					ApplicationID: "APP-1",
154					ProcessedOn:   MustParseDate(tc.currentEnd),
155					ArchiveIDs:    []string{"A-1"},
156				})
157				if err != nil || r.Status != CheckReady {
